import{_ as l,l as r,o as e,c as o,v as t,p as s,x as i,d,i as c,S as E}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"仿射期限结构","description":"","frontmatter":{"title":"仿射期限结构","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/affine-yield-curve.md","filePath":"econ/affine-yield-curve.md","lastUpdated":1789023840000}'),p={name:"econ/affine-yield-curve.md"};function h(B,a,u,f,A,_){const n=r("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="仿射期限结构" tabindex="-1">仿射期限结构 <a class="header-anchor" href="#仿射期限结构" aria-label="Permalink to &quot;仿射期限结构&quot;">​</a></h1><div class="epigraph"><p>若短期利率与风险价格对状态仿射，债券价格就是指数仿射，收益率对因子线性；曲线是状态变量的函数，不是某一档国债的挂单价。</p><footer>—— Duffie and Kan, A Yield-Factor Model of Interest Rates, Mathematical Finance, 1996；对照 Piazzesi 对仿射期限结构模型的综述</footer></div><p><a href="/econ/liquidity-habitat-term">上一课</a>给 EH 补上期限溢价的均衡语言：价格风险、分割、栖息地。\\(\\ell^{(n)}\\) 仍是与 \\(m\\) 的协方差，尚未给出一条可处理的动态曲线。本课缺口是仿射期限结构（DTSM 的理论核）：用低维因子生成整条 \\(y^{(n)}\\)。不是国债微观结构，不重写限价簿。主干下一课在等式处停，协议从队列处起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>栖息地说明 \\(\\ell^{(n)}\\) 可以随相对供给与客户群动，但没有给出 \\(y_n\\) 如何随几个状态一起走。Vasicek、CIR 已经是单因子特例：短期利率均值回复，债券价格有闭式。Duffie 与 Kan（1996）把家族收成仿射：状态 \\(X\\) 的漂移与扩散协方差对 \\(X\\) 仿射，短期利率 \\(r=\\delta_0+\\delta_1\\cdot X\\)，风险中性下仍仿射，则零息价格 \\(P(n,X)=\\exp(A(n)+B(n)\\cdot X)\\)，到期收益率对 \\(X\\) 线性。这就是因子收益率模型。</p><p>缺口是把 EH 加溢价写成一个状态空间，而不是把 on-the-run、特殊券、可交割最便宜提前写进本栏。那些是量化栏的券与协议；本课的对象是 \\(P_n=\\mathrm{E}[m^{(n)}]\\) 的仿射特化。</p><p><span class="marginnote">仿射：收益率 \\(y_n\\) 对因子线性。高斯仿射里因子正态；CIR 式平方根保证利率为正但破坏高斯。DTSM 是这类动态期限结构模型的统称，不是某一家央行的拟合软件名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在风险中性测度下设定 \\(X\\) 的仿射扩散，选 \\(r\\) 仿射，解 ODE 得 \\(A(n),B(n)\\)。物理测度上的风险价格若也对 \\(X\\) 仿射，则两测度的漂移差可识别为期限溢价的来源——正是上一课 \\(\\ell^{(n)}\\) 的动态版。因子可以叫「水平、斜率、曲率」，那是载荷 \\(B(n)\\) 的形状，不必先有主成分故事。</p>',9)),(e(),s(E,null,{default:i(()=>[c(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20HAB%5B%22%E6%A0%96%E6%81%AF%E5%9C%B0%3A%20%E6%BA%A2%E4%BB%B7%E4%B8%BA%E4%BD%95%E6%8C%89%E5%88%B0%E6%9C%9F%E6%8E%92%22%5D%20--%3E%20AFF%5B%22%E4%BB%BF%E5%B0%84%3A%20%E6%BA%A2%E4%BB%B7%E5%A6%82%E4%BD%95%E9%9A%8F%E5%9B%A0%E5%AD%90%E5%8A%A8%22%5D%0A%20%20AFF%20--%3E%20Y%5B%22y_n%20%3D%20a(n)%20%2B%20b(n)%20%E7%82%B9%20X%22%5D%0A%20%20Y%20--%3E%20STOP%5B%22%E5%9D%87%E8%A1%A1%E6%9B%B2%E7%BA%BF%E5%9C%A8%E6%AD%A4%22%5D%0A%20%20STOP%20--%3E%20LOB%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E7%90%86%E8%AE%BA%E5%81%9C%2C%20%E7%B0%BF%E6%98%AF%E5%8D%8F%E8%AE%AE%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>Piazzesi 的综述把识别、测量误差、宏观因子（货币政策规则进 \\(X\\)）写成同一家族的扩展。本课只取 Duffie–Kan 的核：闭式来自仿射，不是来自「国债流动性分层」。相对供给若被写进 \\(X\\) 的一个分量，栖息地与仿射可以接；盘口厚度仍不是 \\(X\\)。</p><h3 id="不要把-当成某一档报价" tabindex="-1">不要把 \\(y_n\\) 当成某一档报价 <a class="header-anchor" href="#不要把-当成某一档报价" aria-label="Permalink to &quot;不要把 $y_n$ 当成某一档报价&quot;">​</a></h3><p>模型产出的是贴现函数。哪一张券、哪一个到期惯例、是否 cheapest-to-deliver，是把贴现函数映射到发票价格的约定。本栏不进入这些约定，以免把 DTSM 吞进微观结构。下一课 <a href="/econ/to-limit-order-book">到限价簿</a>会把这句话执行到底：理论停；簿是协议。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是指数仿射把条件期望变成 ODE。无套利要求同一 \\(X\\) 给所有到期定价；载荷 \\(B(n)\\) 描述久期对因子的敏感，期限溢价是风险价格乘这些敏感。EH 是风险价格为零（或与债券回报不相关）的特例；Hicks 式流动性偏好对应风险价格使长端 \\(B(n)\\) 贡献正的 \\(\\ell^{(n)}\\)。供给冲击若移动栖息地，在仿射里表现为 \\(X\\) 或风险价格的跳，仍是均衡状态，不是某一档时间优先。</p><p>货币政策可以把短端钉在规则上，长端由 \\(B(n)\\) 把预期与溢价推出去——非常规政策扭的是 \\(X\\) 里的期限供给或风险价格，上一课已经留过通道。本课不估计 QE 基点。</p><p><span class="marginnote">Duffie and Kan, <em>Mathematical Finance</em> 1996。Piazzesi 的 Handbook 章节是对照综述。不要发明 arXiv。不要把仿射写成「三因子股票模型」的债券版；截面股票因子在量化栏。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在本栏做 Fama–Bliss 回归，不要拟合 Nelson–Siegel 再宣布栖息地被证实。也不要把国债 ETF、期货基差、回购特殊券写进来。因子实证与交易协议一律换栏。本课之后不是再写一个均衡模型，而是承认曲线上的数字还没有交易程序。</p><p>后课默认：仿射 DTSM 用低维状态生成整条收益率曲线，期限溢价是仿射风险价格；这不是微观结构。下一课把本栏主干停在限价簿之前。打开 <a href="/quant/lob-structure">/quant/lob-structure</a> 时，只携带「应当有一个均衡价格」，不携带队列几何，也不携带哪一档国债的挂单。</p><p>高斯仿射可以让利率为负；那是模型代价，不是对 ZLB 的描述。平方根与影子利率是后补，本课不展开。</p><p>宏观因子（通胀、产出缺口）可以放进 \\(X\\)，使短端规则与长端溢价在同一个仿射里。那仍是均衡 DTSM，不是把 Phillips 曲线画到国债盘口上。测量误差、调查利率、或用掉期代替国债，属于把 \\(y_n\\) 接到哪一套报价，后课交接时一并放下。</p><p>本栏读者打开 <a href="/econ/to-limit-order-book">到限价簿</a> 时，只携带仿射曲线与栖息地溢价，不携带 tick、队列与特殊券。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Duffie–Kan：仿射状态 ⇒ 债券价格指数仿射 ⇒ 收益率对因子线性。</li><li>这是 EH 与栖息地溢价的动态特化，不是国债盘口理论。</li><li>主干下一课交接：理论停，簿是协议；不重写限价簿。</li><li>\\(y_n\\) 不是某一档挂单价；特殊券与 CTD 是映射约定，换栏再谈。</li><li>打开 <a href="/quant/lob-structure">/quant/lob-structure</a> 时不携带队列几何。</li><li>高斯仿射可让利率为负，那是模型代价，不是对下限的描述。</li><li>出处：Duffie and Kan, <em>Mathematical Finance</em> 1996；对照 Piazzesi 对仿射 DTSM 的综述。</li></ul>',15))])}const T=l(p,[["render",h]]);export{D as __pageData,T as default};
